// next-prompt-core 0.1.0 (fb0149f). Generated by scripts/vendor.mjs: change that repository, not this copy.
// Pure suggestion logic: transcript building, the model prompt, and output
// filtering. One file with no imports and no host or Node APIs, so a Claude
// Code mod can hold a copy of it and a Node host can depend on it.

const MAX_SUGGESTION_CHARS = 100;
export const MAX_SUGGESTIONS = 3;
const MAX_ORIGINAL_REQUEST_CHARS = 2_500;
const MAX_USER_TURN_CHARS = 2_500;
const MAX_ASSISTANT_TURN_CHARS = 6_000;

/** What a host passes to its model call unless its user chose otherwise. */
export const SUGGESTION_DEFAULTS = {
	model: "sonnet",
	effort: "low",
	maxTokens: 400,
	timeoutSeconds: 20,
	maxContextChars: 10_000,
} as const;

/** What to suggest and what not to. A host with a prompt of its own embeds this. */
export const SUGGESTION_RULES = `Your job is to predict what THEY would type - not what you think they should do.

THE TEST: Would they think "I was just about to type that"?

EXAMPLES:
User asked "fix the bug and run tests", bug is fixed, tests not run → "run the tests"
The assistant asks approval for what the user asked for → "yes, delete them"
The assistant recommends one option, or the user stated a preference → the option they would pick
The assistant offers choices ("fix 1 or fix 2?") → the choices, likeliest first
The original request has a step left, such as "then commit" → that step: "commit this"
After error or misunderstanding → [] (let them assess/correct)

Be specific: "run the tests" beats "continue".

Give up to ${MAX_SUGGESTIONS} suggestions, best first. Each one must make the assistant do something different. The same answer in other words is one suggestion: "yes", "ok" and "yes, publish it" all approve; "run the tests" and "run all tests" both run them.

A second or third suggestion is a real alternative the user might pick instead:
- another option the assistant offered
- a look before acting: "show me the text first"
- a no, when declining is a real choice: "no, leave them"
One obvious next step with no real alternative is one suggestion. Do not invent an edit, a review or a refusal just to fill another slot.

Approval asked for publishing a post whose text the user has not seen:
GOOD: ["yes, publish it", "show me the final text first"]
Approval asked for publishing a post the user already reviewed:
GOOD: ["yes, publish it"]
BAD: ["yes, publish it", "yes"] (the same approval twice)
BAD: ["publish it", "go ahead and post"] (the same action reworded)

Before suggesting, separate what the assistant already did, is doing or promised to do from what is still the user's to decide. Return [] when:
- the assistant says work is running, or promises to do it next: the user just waits
- the task is finished and the user asked for nothing more
- the only reply would be an acknowledgment, praise or a status question
- the assistant asks for a fact only the user knows

NEVER SUGGEST:
- Repeating work already done, such as committing what is committed
- Steps the user did not ask for, such as pushing, deploying or publishing, unless the assistant explicitly asks the user to approve that step and the user has not ruled it out: then put the approval first, since users mostly approve a step the assistant proposes and only confirm it because a rule makes the assistant ask; add a no after it when declining is a real choice
- Invented names, values or preferences
- Evaluative ("looks good", "thanks")
- Questions ("what about...?")
- Assistant-voice ("Let me...", "I'll...", "Here's...")
- Multiple sentences in one suggestion`;

export const SUGGESTION_STYLE = `Format: 2-12 words each, match the user's style and language.`;

export const SYSTEM_PROMPT = `[SUGGESTION MODE: Suggest what the user might naturally type next into the coding assistant.]

FIRST: Look at the user's recent messages and original request.

${SUGGESTION_RULES}

${SUGGESTION_STYLE}

Reply with ONLY JSON: {"suggestions": ["<text>", ...]}, or {"suggestions": []} when nothing the user would type next is grounded in what they said.`;

type Row = Record<string, unknown>;

function asRow(value: unknown): Row | undefined {
	return typeof value === "object" && value !== null && !Array.isArray(value)
		? (value as Row)
		: undefined;
}

/** One transcript message: the host drops tool calls and their results. */
export type Message = { role: "user" | "assistant"; text: string };

/** `userText` gives the text the user typed; a message that gives "" counts as none. */
export type TextOptions = { userText?: (text: string) => string };

const trimmed = (text: string) => text.trim();

// Text Claude Code adds to a user message that the user did not type.
const INJECTED_BLOCKS =
	/<(system-reminder|local-command-caveat|local-command-stdout|local-command-stderr|command-message)>[\s\S]*?<\/\1>/g;
const COMMAND_NAME = /<command-name>([\s\S]*?)<\/command-name>/;
const COMMAND_ARGS = /<command-args>([\s\S]*?)<\/command-args>/;

/** The text the user typed: a slash command as typed, Claude Code's injected blocks removed. */
export function typedText(text: string): string {
	const command = COMMAND_NAME.exec(text)?.[1]?.trim();
	if (command) return `${command} ${COMMAND_ARGS.exec(text)?.[1]?.trim() ?? ""}`.trim();
	return text.replace(INJECTED_BLOCKS, "").trim();
}

/**
 * The last assistant turn's text: every assistant message since the last
 * prompt the user typed, joined across the tool calls between them.
 */
export function lastAnswer(messages: readonly Message[], { userText = trimmed }: TextOptions = {}): string {
	const parts: string[] = [];
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		const message = messages[index];
		if (!message) continue;
		if (message.role === "user") {
			if (userText(message.text)) break;
			continue;
		}
		parts.unshift(message.text.trim());
	}
	return parts.filter(Boolean).join("\n\n");
}

function truncateMiddle(value: string, maxLength: number): string {
	if (value.length <= maxLength) return value;
	const half = Math.floor((maxLength - 7) / 2);
	return `${value.slice(0, half)}\n[...]\n${value.slice(-half)}`;
}

/**
 * Build the model input from the session's transcript: the first request and
 * the newest turns that fit maxContextChars. Returns undefined when there is
 * no completed exchange.
 */
export function buildSuggestionPrompt(
	messages: readonly Message[],
	maxContextChars: number,
	{ userText = trimmed }: TextOptions = {},
): string | undefined {
	const conversation: Array<{ role: "User" | "Assistant"; text: string }> = [];
	for (const message of messages) {
		const text = message.role === "user" ? userText(message.text) : message.text.trim();
		if (!text) continue;
		const role = message.role === "user" ? "User" : "Assistant";
		// One turn's assistant text arrives as several messages around its tool calls.
		const last = conversation.at(-1);
		if (role === "Assistant" && last?.role === role) last.text = `${last.text}\n\n${text}`;
		else conversation.push({ role, text });
	}

	const firstUserIndex = conversation.findIndex((entry) => entry.role === "User");
	const firstUser = conversation[firstUserIndex];
	if (!firstUser || conversation.at(-1)?.role !== "Assistant") return undefined;

	const recent: string[] = [];
	let length = 0;
	for (let index = conversation.length - 1; index > firstUserIndex; index -= 1) {
		const entry = conversation[index];
		if (!entry) continue;
		const limit = entry.role === "Assistant" ? MAX_ASSISTANT_TURN_CHARS : MAX_USER_TURN_CHARS;
		const rendered = `${entry.role}: ${truncateMiddle(entry.text, limit)}`;
		if (recent.length > 0 && length + rendered.length > maxContextChars) break;
		recent.push(rendered);
		length += rendered.length;
	}
	recent.reverse();

	return `Original user request:\n${truncateMiddle(firstUser.text, MAX_ORIGINAL_REQUEST_CHARS)}\n\nRecent conversation:\n${recent.join("\n\n")}`;
}

/**
 * The suggestion texts from a `{"suggestions": string[]}` reply, or a
 * `{"suggestion": string | null}` one, which a custom prompt may ask for. A
 * bare `[]`, `null` or a blank reply is no suggestion; undefined for a reply
 * that is not JSON.
 */
function replyTexts(output: string): unknown[] | undefined {
	const body = output
		.trim()
		.replace(/^```(?:json)?\s*/i, "")
		.replace(/\s*```$/i, "")
		.trim();
	if (/^(\[\s*\]|null)?$/.test(body)) return [];
	try {
		const parsed = asRow(JSON.parse(body));
		if (Array.isArray(parsed?.suggestions)) return parsed.suggestions;
		return [parsed?.suggestion];
	} catch {
		return undefined;
	}
}

/**
 * Whether the model chose to suggest nothing: `[]`, `null` or a blank reply,
 * as opposed to suggestions the checks rejected or a malformed reply.
 */
export function isEmptyReply(output: string): boolean {
	return replyTexts(output)?.every((value) => value === null || value === "") ?? false;
}

/** One suggestion, unquoted, or undefined when it cannot fit one row. */
function cleanSuggestion(value: unknown): string | undefined {
	if (typeof value !== "string") return undefined;
	const suggestion = value
		.trim()
		.replace(/^(["'`“«])([\s\S]+)(["'`”»])$/, "$2")
		.trim();
	if (!suggestion || suggestion.length >= MAX_SUGGESTION_CHARS || /[\r\n]/.test(suggestion)) return undefined;
	return suggestion;
}

/**
 * Whether two suggestions are the same text but for case, spacing and
 * sentence-final punctuation. Rewordings are left to the prompt.
 */
export function isEcho(later: string, earlier: string): boolean {
	// Only sentence-final punctuation is ignored: "use C++" is not "use C".
	const plain = (text: string) => text.toLowerCase().replace(/[.!?…。！？]+$/u, "").replace(/\s+/g, " ").trim();
	return plain(later) === plain(earlier);
}

/**
 * Read raw model output: at most MAX_SUGGESTIONS distinct suggestions, best
 * first; empty means "show nothing". What to suggest is the prompt's business:
 * the checks here are about form, in any language.
 */
export function normalizeSuggestions(output: string): string[] {
	return filterSuggestions(replyTexts(output) ?? []);
}

/** The same for values a host already took out of its own reply format. */
export function filterSuggestions(values: readonly unknown[]): string[] {
	const suggestions: string[] = [];
	for (const value of values) {
		const suggestion = cleanSuggestion(value);
		if (!suggestion) continue;
		if (suggestions.some((kept) => isEcho(suggestion, kept))) continue;
		suggestions.push(suggestion);
		if (suggestions.length === MAX_SUGGESTIONS) break;
	}
	return suggestions;
}

/** A short FNV-1a hash of `parts`, to tell one request's inputs from another's. */
export function fingerprint(...parts: readonly string[]): string {
	let hash = 0x811c9dc5;
	for (const char of parts.join("\u0000")) {
		hash ^= char.codePointAt(0) ?? 0;
		hash = Math.imul(hash, 0x01000193) >>> 0;
	}
	return hash.toString(16).padStart(8, "0");
}
